def is_deletion_request(request_text: str) -> bool:
    """Return whether text clearly authorizes account or personal data deletion."""
    text = (request_text or "").strip()
    if not text or not _DELETION_TERMS.search(text):
        return False
    if _NEGATED_DELETE.search(text):
        return False
    if _NON_DELETE_ONLY.search(text) and not re.search(
        r"\b(?:please|I want|I wish|request|would like|quiero|solicito|"
        r"je veux|demande|ich möchte|quero)\\b.{0,100}"
        r"(?:delete|erase|close|removal|eliminar|borrar|supprimer|"
        r"effacer|löschen|entfernen|apagar|remover|gdpr|forgotten)",
        text,
        re.IGNORECASE | re.DOTALL,
    ):
        return False
    return True


def audit_case(
    case_row: Dict[str, Any], identity: ResolvedIdentity, conn: sqlite3.Connection
) -> Tuple[str, List[AuditStep]]:
    if not is_deletion_request(str(case_row.get("request_text", ""))):
        return "NOT_APPLICABLE", []

    cutoff = _time_key(case_row.get("audit_at"))
    requested = _time_key(case_row.get("requested_at"))
    findings: List[Tuple[AuditStep, Optional[str]]] = []
    activity_rows = conn.execute(
        "SELECT activity_id,event_time,event_type,source_system,target_system,"
        "resource_id,reported_result,details FROM system_activity "
        "WHERE event_time <= ? ORDER BY event_time,activity_id",
        (case_row.get("audit_at", ""),),
    ).fetchall()
    activity = [
        dict(
            zip(
                (
                    "activity_id", "event_time", "event_type", "source_system",
                    "target_system", "resource_id", "reported_result", "details",
                ),
                row,
            )
        )
        for row in activity_rows
    ]
    matching_activity = [
        event for event in activity if _contains_identity(event, identity)
    ]

    disabled = {
        (event.get("resource_id", ""), event.get("source_system", ""))
        for event in matching_activity
        if event.get("event_type") == "DISABLE_DATA_FLOW"
    }
    blocked = {
        event.get("resource_id", "")
        for event in matching_activity
        if event.get("event_type") == "BLOCK_RESTORE"
    }
    for event in matching_activity:
        event_time = _time_key(event.get("event_time"))
        event_type = event.get("event_type")
        resource_id = event.get("resource_id") or ""
        system_id = event.get("source_system") or ""
        if (
            event_type in {"SYNC_RECORD", "INDEX_RECORD", "UPDATE_RECORD", "EXPORT_DATA"}
            and requested < event_time
            and event.get("reported_result") == "SUCCESS"
            and (resource_id, system_id) not in disabled
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_ACTIVE_DATA_FLOW", "ACTIVE",
                        event.get("activity_id", ""),
                    ),
                    None,
                )
            )
        elif (
            event_type in {"BACKUP_SNAPSHOT", "RESTORE_BACKUP"}
            and resource_id not in blocked
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_RESTORE_RISK", "ACTIVE",
                        event.get("activity_id", ""),
                    ),
                    None,
                )
            )

    manifest: Dict[str, Tuple[str, str, str]] = {}
    for file_id, file_path, origin, captured_at in conn.execute(
        "SELECT file_id,file_path,origin,captured_at FROM evidence_files"
    ):
        manifest[Path(file_path).stem.casefold()] = (
            file_id, _time_key(captured_at), origin
        )

    snapshot_registry = (
        {row[0] for row in conn.execute(
            "SELECT table_name FROM _northstar_snapshot_tables"
        )}
        if conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='_northstar_snapshot_tables'"
        ).fetchone()
        else set()
    )
    seen = set()
    for table, columns in _tables(conn):
        lower_table = table.casefold()
        if table in {
            "user_identities", "user_audit_log", "system_activity",
            "deletion_rules", "evidence_files", "deletion_requests",
        }:
            continue
        if any(word in lower_table for word in ("tombstone", "account")):
            category = "tombstone"
        elif any(word in lower_table for word in ("analytics", "telemetry")):
            category = "analytics"
        elif any(
            word in lower_table
            for word in (
                "profile", "search", "cache", "export", "support",
                "customer_data",
            )
        ):
            category = "delete"
        else:
            continue

        table_prefix = re.match(r"(.+?)__", table)
        manifest_entry = (
            manifest.get(table_prefix.group(1).casefold())
            if table_prefix
            else None
        )
        evidence_id = manifest_entry[0] if manifest_entry else ""
        if manifest_entry and manifest_entry[1] > cutoff:
            continue
        if table not in snapshot_registry and manifest_entry is None:
            continue

        escaped_table = table.replace('"', '""')
        for raw in conn.execute(f'SELECT * FROM "{escaped_table}"'):
            record = dict(zip(columns, raw))
            if not _contains_identity(record, identity):
                continue
            row_time = next(
                (
                    record[column]
                    for column in columns
                    if column.casefold()
                    in {
                        "captured_at", "snapshot_at", "valid_at",
                        "event_time", "created_at", "updated_at",
                    }
                    and record[column]
                ),
                None,
            )
            if row_time and _time_key(row_time) > cutoff:
                continue

            system_id = str(
                record.get("system_id")
                or record.get("source_system")
                or record.get("system")
                or "unknown_system"
            )
            resource_id = str(
                record.get("resource_id")
                or record.get("record_id")
                or record.get("id")
                or record.get("user_id")
                or "unknown_resource"
            )
            key = (table, resource_id, category)
            if key in seen:
                continue
            seen.add(key)

            row_text = _row_values(record)
            is_tombstone = (
                category == "tombstone"
                or "tombstone" in row_text
                or "account_tombstone" in row_text
            )
            direct_identifiers = (
                set(identity.emails)
                | set(identity.phones)
                | set(identity.names)
                | set(identity.email_hashes)
            )
            if is_tombstone:
                if any(
                    value and str(value).casefold() in row_text
                    for value in direct_identifiers
                ):
                    findings.append(
                        (
                            AuditStep(
                                "FINDING", system_id, resource_id,
                                "REPORT_EXPOSED_PII", "PRESENT", evidence_id,
                            ),
                            "REDACT",
                        )
                    )
            elif category == "analytics":
                findings.append(
                    (
                        AuditStep(
                            "FINDING", system_id, resource_id,
                            "REPORT_EXPOSED_PII", "PRESENT", evidence_id,
                        ),
                        "ANONYMIZE",
                    )
                )
            else:
                findings.append(
                    (
                        AuditStep(
                            "FINDING", system_id, resource_id,
                            "REPORT_REMAINING_RECORD", "PRESENT", evidence_id,
                        ),
                        "DELETE",
                    )
                )

    unique_findings: Dict[
        Tuple[str, str, str, str],
        Tuple[AuditStep, Optional[str]],
    ] = {}
    for finding, treatment in findings:
        unique_findings[
            (
                finding.operation,
                finding.system_id,
                finding.resource_id,
                finding.evidence_id,
            )
        ] = (finding, treatment)
    findings = list(unique_findings.values())

    if findings:
        return "INCOMPLETE", expand_findings_to_plan(findings)

    verifications: List[AuditStep] = []
    for file_id, file_path, _origin, captured_at in conn.execute(
        "SELECT file_id,file_path,origin,captured_at "
        "FROM evidence_files ORDER BY captured_at,file_id"
    ):
        if (
            _time_key(captured_at) <= cutoff
            and any(
                word in Path(file_path).name.casefold()
                for word in ("account", "profile", "deletion")
            )
        ):
            resource_id = next(
                iter(sorted(identity.linked_resources)),
                next(
                    iter(sorted(identity.user_ids)),
                    case_row.get("case_id", "unknown"),
                ),
            )
            verifications.append(
                AuditStep(
                    "VERIFICATION", "account_service", resource_id,
                    "VERIFY_RECORD_ABSENT", "ABSENT", file_id,
                )
            )
            break

    if not verifications:
        return "INCOMPLETE", []
    return "COMPLETE", verifications


def validate_samples(
    conn: sqlite3.Connection, dataset_dir: Path = Path("dataset")
) -> float:
    with (dataset_dir / "sample_deletion_requests.csv").open(
        "r", encoding="utf-8-sig", newline=""
    ) as source:
        cases = list(csv.DictReader(source))
    with (dataset_dir / "sample_output.csv").open(
        "r", encoding="utf-8-sig", newline=""
    ) as source:
        expected_rows = {
            row["case_id"]: row for row in csv.DictReader(source)
        }

    matched_status = 0
    matched_steps = 0
    for case in cases:
        identity = resolve_identity(case["email"], conn)
        status, steps = audit_case(case, identity, conn)
        actual_steps = build_steps_json(status, steps)
        expected = expected_rows.get(case["case_id"])
        if expected:
            matched_status += status == expected["deletion_status"]
            try:
                matched_steps += (
                    json.loads(actual_steps)
                    == json.loads(expected["steps_json"])
                )
            except (json.JSONDecodeError, TypeError):
                pass

    status_accuracy = matched_status / max(1, len(expected_rows))
    steps_accuracy = matched_steps / max(1, len(expected_rows))
    print(
        f"Sample validation: status accuracy={status_accuracy:.2%}; "
        f"exact steps={steps_accuracy:.2%} ({len(expected_rows)} cases)"
    )
    return (status_accuracy + steps_accuracy) / 2


def run_pipeline(
    dataset_dir: Path = Path("dataset"),
    output_csv: Path = Path("output.csv"),
) -> None:
    conn = init_database(dataset_dir)
    try:
        validate_samples(conn, dataset_dir)
        with (dataset_dir / "deletion_requests.csv").open(
            "r", encoding="utf-8-sig", newline=""
        ) as source:
            cases = sorted(csv.DictReader(source), key=lambda row: row["case_id"])

        tracker = UsageTracker(total_cases=len(cases))
        output_csv.parent.mkdir(parents=True, exist_ok=True)
        with output_csv.open("w", encoding="utf-8", newline="") as target:
            writer = csv.DictWriter(
                target,
                fieldnames=["case_id", "deletion_status", "steps_json"],
                lineterminator="\n",
            )
            writer.writeheader()
            for case in cases:
                identity = resolve_identity(case["email"], conn)
                status, steps = audit_case(case, identity, conn)
                writer.writerow(
                    {
                        "case_id": case["case_id"],
                        "deletion_status": status,
                        "steps_json": build_steps_json(status, steps),
                    }
                )

        with output_csv.open("r", encoding="utf-8-sig", newline="") as source:
            written = list(csv.DictReader(source))
        if (
            len(written) != len(cases)
            or [row["case_id"] for row in written]
            != [row["case_id"] for row in cases]
        ):
            raise AssertionError(
                "Output must contain exactly one row per case in sorted order"
            )
        tracker.export_markdown()
    finally:
        conn.close()


if __name__ == "__main__":
    run_pipeline()

