            key = (table, resource, category)
            if key in seen:
                continue
            seen.add(key)
            text = _row_values(record)
            tombstone = category == "tombstone" or "tombstone" in text or "account_tombstone" in text
            if tombstone:
                has_direct = any(value and str(value).casefold() in text for value in token_sets["direct"])
                if has_direct:
                    findings.append((AuditStep("FINDING", system, resource, "REPORT_EXPOSED_PII", "PRESENT", evidence_id), "REDACT"))
            elif category == "analytics":
                findings.append((AuditStep("FINDING", system, resource, "REPORT_EXPOSED_PII", "PRESENT", evidence_id), "ANONYMIZE"))
            else:
                findings.append((AuditStep("FINDING", system, resource, "REPORT_REMAINING_RECORD", "PRESENT", evidence_id), "DELETE"))

    valid_evidence_ids = {
        str(row[0]) for row in conn.execute(
            "SELECT file_id FROM evidence_files WHERE file_id IS NOT NULL"
        )
    }
    valid_evidence_ids.update(
        str(row[0]) for row in conn.execute(
            "SELECT activity_id FROM system_activity WHERE activity_id IS NOT NULL"
        )
    )
    findings = [
        (finding, treatment)
