def audit_case(
    case_row: Dict[str, Any], identity: ResolvedIdentity, conn: sqlite3.Connection
) -> Tuple[str, List[AuditStep]]:
    if not is_deletion_request(str(case_row.get("request_text", ""))):
        return "NOT_APPLICABLE", []

    cutoff = _time_key(case_row.get("audit_at"))
    requested = _time_key(case_row.get("requested_at"))
    findings: List[Tuple[AuditStep, Optional[str]]] = []

    activity_rows = conn.execute(
        "SELECT activity_id,event_time,event_type,source_system,target_system,"
        "resource_id,reported_result,details FROM system_activity "
        "WHERE event_time <= ? ORDER BY event_time,activity_id",
        (case_row.get("audit_at", ""),),
    ).fetchall()
    activity_fields = (
        "activity_id", "event_time", "event_type", "source_system",
        "target_system", "resource_id", "reported_result", "details",
    )
    activity = [dict(zip(activity_fields, row)) for row in activity_rows]
    matching_activity = [
        event for event in activity if _contains_identity(event, identity)
    ]

    disabled = {
        (event.get("resource_id", ""), event.get("source_system", ""))
        for event in matching_activity
        if event.get("event_type") == "DISABLE_DATA_FLOW"
    }
    blocked = {
        event.get("resource_id", "")
        for event in matching_activity
        if event.get("event_type") == "BLOCK_RESTORE"
    }
    for event in matching_activity:
        event_time = _time_key(event.get("event_time"))
        event_type = event.get("event_type")
        resource_id = event.get("resource_id") or ""
        system_id = event.get("source_system") or ""
        activity_id = event.get("activity_id") or ""
        if (
            event_type in {"SYNC_RECORD", "INDEX_RECORD", "UPDATE_RECORD", "EXPORT_DATA"}
            and requested < event_time
            and event.get("reported_result") == "SUCCESS"
            and (resource_id, system_id) not in disabled
            and activity_id
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_ACTIVE_DATA_FLOW", "ACTIVE", activity_id,
                    ),
                    None,
                )
            )
        elif (
            event_type in {"BACKUP_SNAPSHOT", "RESTORE_BACKUP"}
            and resource_id not in blocked
            and activity_id
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_RESTORE_RISK", "ACTIVE", activity_id,
                    ),
                    None,
                )
            )

    manifest_rows = [
        (str(file_id), str(file_path), str(origin or ""), _time_key(captured_at))
        for file_id, file_path, origin, captured_at in conn.execute(
            "SELECT file_id,file_path,origin,captured_at FROM evidence_files"
        )
        if file_id and _time_key(captured_at) <= cutoff
    ]
    manifest = {
        Path(file_path).stem.casefold(): (file_id, captured_at, origin)
        for file_id, file_path, origin, captured_at in manifest_rows
    }
    sql_snapshots = [
        entry
        for entry in manifest_rows
        if Path(entry[1]).suffix.casefold() == ".sql"
    ]
    latest_sql_snapshot = max(
        sql_snapshots,
        key=lambda entry: (entry[3], entry[0]),
        default=None,
    )

    def infer_system(
        record: Dict[str, Any], table_name: str, resource_id: str
    ) -> str:
        explicit = next(
            (
                record.get(key)
                for key in ("system_id", "source_system", "system")
                if record.get(key) and str(record[key]).strip()
            ),
            None,
        )
        if explicit:
            return str(explicit).strip()

        key = f"{resource_id} {table_name}".casefold()
        if key.startswith("account_") or any(
            marker in key
            for marker in ("customer_profiles", "customer_data", "tombstone")
        ):
            return "account_service"
        if key.startswith("analytics_") or "telemetry" in key:
            return "analytics_platform"
        if key.startswith("search_") or "search_" in key:
            return "search_service"
        if key.startswith("support_") or "support_" in key:
            return "support_platform"
        if key.startswith("audit_record_") or "security_" in key:
            return "security_service"
        if key.startswith("backup_") or "backup_" in key:
            return "backup_service"
        if key.startswith("data_flow_") or "data_flow_" in key:
            return "data_sync_service"
        return "account_service"

    def snapshot_evidence(table_name: str) -> str:
        table_key = table_name.casefold()
        candidates = []
        for file_id, file_path, _origin, captured_at in manifest_rows:
            path = Path(file_path)
            stem = path.stem.casefold()
            if (
                path.suffix.casefold() == ".sql"
                and (stem in table_key or table_key in stem)
            ):
                candidates.append((captured_at, file_id))
        if candidates:
            return max(candidates)[1]
        return latest_sql_snapshot[0] if latest_sql_snapshot else ""

