    disabled = set()
    blocked = set()
    for event in matching_activity:
        if event["event_type"] == "DISABLE_DATA_FLOW":
            disabled.add((event.get("resource_id", ""), event.get("source_system", "")))
        elif event["event_type"] == "BLOCK_RESTORE":
            blocked.add(event.get("resource_id", ""))
    for event in matching_activity:
        event_time = _time_key(event.get("event_time"))
        kind = event.get("event_type")
        resource = event.get("resource_id") or ""
        system = event.get("source_system") or ""
        if not system or system == "unknown_system":
            resource_key = resource.casefold()
            if resource_key.startswith(("analytics_", "telemetry_")):
                system = "analytics_platform"
            elif resource_key.startswith("search_"):
                system = "search_service"
            elif resource_key.startswith("support_"):
                system = "support_platform"
            elif resource_key.startswith(("backup_",)):
                system = "backup_service"
            elif resource_key.startswith("data_flow_"):
                system = "data_sync_service"
            elif resource_key.startswith(("audit_record_", "security_")):
                system = "security_service"
            else:
                system = "account_service"
        if kind in {"SYNC_RECORD", "INDEX_RECORD", "UPDATE_RECORD", "EXPORT_DATA"} and requested < event_time and event.get("reported_result") == "SUCCESS" and (resource, system) not in disabled:
            findings.append((AuditStep("FINDING", system, resource, "REPORT_ACTIVE_DATA_FLOW", "ACTIVE", event.get("activity_id", "")), None))
        elif kind in {"BACKUP_SNAPSHOT", "RESTORE_BACKUP"} and resource not in blocked:
            findings.append((AuditStep("FINDING", system, resource, "REPORT_RESTORE_RISK", "ACTIVE", event.get("activity_id", "")), None))

    manifest_rows = [
        (str(fid), str(path), str(origin or ""), _time_key(captured))
        for fid, path, origin, captured in conn.execute(
            "SELECT file_id,file_path,origin,captured_at FROM evidence_files"
        )
        if fid and _time_key(captured) <= cutoff
    ]
    manifest = {
        Path(path).stem.casefold(): (fid, captured, origin)
        for fid, path, origin, captured in manifest_rows
    }
    sql_snapshots = [item for item in manifest_rows if Path(item[1]).suffix.casefold() == ".sql"]
    latest_sql_snapshot = max(sql_snapshots, key=lambda item: (item[3], item[0]), default=None)

    def infer_system(record: Dict[str, Any], table_name: str, resource_id: str) -> str:
        explicit = next(
            (record.get(key) for key in ("system_id", "source_system", "system")
             if record.get(key) and str(record[key]).strip()),
            None,
        )
        if explicit:
            return str(explicit).strip()
        key = f"{resource_id} {table_name}".casefold()
        if key.startswith("account_") or any(x in key for x in ("customer_profiles", "customer_data", "tombstone")):
            return "account_service"
        if key.startswith("analytics_") or "telemetry" in key:
            return "analytics_platform"
        if key.startswith("search_") or "search_" in key:
            return "search_service"
        if key.startswith("support_") or "support_" in key:
            return "support_platform"
        if key.startswith("audit_record_") or "security_" in key:
            return "security_service"
        if key.startswith("backup_") or "backup_" in key:
            return "backup_service"
        if key.startswith("data_flow_") or "data_flow_" in key:
            return "data_sync_service"
        return "account_service"

    def snapshot_evidence(table_name: str) -> str:
        table_key = table_name.casefold()
        candidates = []
        for fid, path, _origin, captured in manifest_rows:
            path_obj = Path(path)
            stem = path_obj.stem.casefold()
            if path_obj.suffix.casefold() == ".sql" and (stem in table_key or table_key in stem):
                candidates.append((captured, fid))
        if candidates:
            return max(candidates)[1]
        return latest_sql_snapshot[0] if latest_sql_snapshot else ""

    token_sets = {
        "direct": set(identity.emails) | set(identity.phones) | set(identity.names) | set(identity.email_hashes),
        "all": set(identity.user_ids) | set(identity.emails) | set(identity.phones) | set(identity.names) | set(identity.email_hashes) | set(identity.linked_resources),
    }
    snapshot_registry = {row[0] for row in conn.execute("SELECT table_name FROM _northstar_snapshot_tables")} if conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='_northstar_snapshot_tables'").fetchone() else set()
    seen = set()
    for table, columns in _tables(conn):
        lower = table.casefold()
        if table in {"user_identities", "user_audit_log", "system_activity", "deletion_rules", "evidence_files", "deletion_requests"}:
            continue
        category = None
        if any(word in lower for word in ("tombstone", "account")):
            category = "tombstone"
        elif any(word in lower for word in ("analytics", "telemetry")):
            category = "analytics"
        elif any(word in lower for word in ("profile", "search", "cache", "export", "support", "customer_data")):
            category = "delete"
        if category is None:
            continue
        match = re.match(r"(.+?)__", table)
        manifest_entry = manifest.get(match.group(1).casefold()) if match else None
        evidence_id = manifest_entry[0] if manifest_entry else snapshot_evidence(table)
        # Snapshot tables are immutable captures; non-snapshot logical tables can
        # have row-level validity columns that constrain visibility at audit_at.
        if table not in snapshot_registry and manifest_entry is None:
            continue
        if not evidence_id:
            continue
        safe_table = table.replace('"', '""')
        for raw in conn.execute(f'SELECT * FROM "{safe_table}"'):
            record = dict(zip(columns, raw))
            if not _contains_identity(record, identity):
                continue
            row_time = next((record[c] for c in columns if c.casefold() in {"captured_at", "snapshot_at", "valid_at", "event_time", "created_at", "updated_at"} and record[c]), None)
            if row_time and _time_key(row_time) > cutoff:
                continue
            resource = str(record.get("resource_id") or record.get("record_id") or record.get("id") or record.get("user_id") or table)
            system = infer_system(record, table, resource)
            key = (table, resource, category)
            if key in seen:
                continue
            seen.add(key)
            text = _row_values(record)
            tombstone = category == "tombstone" or "tombstone" in text or "account_tombstone" in text
            if tombstone:
                has_direct = any(value and str(value).casefold() in text for value in token_sets["direct"])
                if has_direct:
                    findings.append((AuditStep("FINDING", system, resource, "REPORT_EXPOSED_PII", "PRESENT", evidence_id), "REDACT"))
            elif category == "analytics":
                findings.append((AuditStep("FINDING", system, resource, "REPORT_EXPOSED_PII", "PRESENT", evidence_id), "ANONYMIZE"))
            else:
                findings.append((AuditStep("FINDING", system, resource, "REPORT_REMAINING_RECORD", "PRESENT", evidence_id), "DELETE"))

    valid_evidence_ids = {
        str(row[0]) for row in conn.execute(
            "SELECT file_id FROM evidence_files WHERE file_id IS NOT NULL"
        )
    }
    valid_evidence_ids.update(
        str(row[0]) for row in conn.execute(
            "SELECT activity_id FROM system_activity WHERE activity_id IS NOT NULL"
        )
    )
    findings = [
        (finding, treatment)
        for finding, treatment in findings
        if finding.evidence_id and finding.evidence_id in valid_evidence_ids
    ]
    findings = [
        (
            AuditStep(
                finding.phase,
                infer_system({}, "", finding.resource_id)
                if not finding.system_id or finding.system_id == "unknown_system"
                else finding.system_id,
                finding.resource_id,
                finding.operation,
                finding.state,
                finding.evidence_id,
            ),
            treatment,
        )
        for finding, treatment in findings
    ]
    # Stable deterministic de-duplication for repeated exports/snapshots of one record.
    unique: Dict[Tuple[str, str, str, str], Tuple[AuditStep, Optional[str]]] = {}
    for finding, treatment in findings:
        unique[(finding.operation, finding.system_id, finding.resource_id, finding.evidence_id)] = (finding, treatment)
    findings = list(unique.values())

