def _strict_row_matches_subject(
    row: Dict[str, Any], identity: ResolvedIdentity
) -> bool:
    """Match typed identity fields or an explicitly linked resource ID."""
    user_ids = {value.casefold() for value in identity.user_ids if value}
    emails = {value.strip().casefold() for value in identity.emails if value}
    phones = {value.strip().casefold() for value in identity.phones if value}
    hashes = {value.casefold() for value in identity.email_hashes if value}
    linked = {value.casefold() for value in identity.linked_resources if value}

    for column, value in row.items():
        if value is None:
            continue
        key = column.casefold()
        candidate = str(value).strip().casefold()
        if key in {"user_id", "subject_user_id", "customer_user_id"}:
            if candidate in user_ids:
                return True
        elif key in {"email", "email_address", "customer_email"}:
            if candidate in emails:
                return True
        elif key in {"phone", "phone_number", "telephone"}:
            if candidate in phones:
                return True
        elif key in {"email_hash", "email_sha256"}:
            if candidate in hashes:
                return True
        elif key in {
            "resource_id", "record_id", "account_id", "document_id", "export_id"
        }:
            if candidate in linked:
                return True
    return False


def _strict_activity_matches(
    event: Dict[str, Any], identity: ResolvedIdentity
) -> bool:
    resource = str(event.get("resource_id") or "").strip().casefold()
    linked = {value.casefold() for value in identity.linked_resources if value}
    if resource and resource in linked:
        return True

    identifiers = (
        set(identity.user_ids)
        | set(identity.emails)
        | set(identity.phones)
        | set(identity.names)
        | set(identity.email_hashes)
    )
    details = str(event.get("details") or "")
    return any(
        value
        and re.search(
            rf"(?<![\w@.+-]){re.escape(value)}(?![\w@.+-])",
            details,
            re.IGNORECASE,
        )
        for value in identifiers
    )


def is_deletion_request(request_text: str) -> bool:
    """Recognize deletion intent while excluding requests with no deletion intent."""
    text = (request_text or "").strip()
    if not text:
        return False

    deletion_terms = re.compile(
        r"\b(?:delet(?:e|es|ed|ing|ion)|eras(?:e|es|ed|ing|ure)|"
        r"clos(?:e|es|ed|ing|ure)|remov(?:e|es|ed|ing|al)|"
        r"elimin(?:ar|o|as|a|amos|an|é|ó|ado|ando|ación)|"
        r"borr(?:ar|o|as|a|ado|ando)|supprim(?:er|e|é|ée|ant|ation)|"
        r"effac(?:er|e|é|ant)|l[öo]sch(?:en|t|te|ung)|entfern(?:en|t|ung)|"
        r"apag(?:ar|o|a|ado|ando)|remov(?:er|o|e|ido|endo)|"
        r"suppression|droit\s+à\s+l['’]oubli|gdpr|forgotten|"
        r"right\s+to\s+be\s+forgotten)\b",
        re.IGNORECASE,
    )
    if not deletion_terms.search(text):
        return False

    explicit_deletion = re.compile(
        r"\b(?:delet(?:e|es|ed|ing|ion)|eras(?:e|es|ed|ing|ure)|"
        r"clos(?:e|es|ed|ing|ure)|remov(?:e|es|ed|ing|al)|"
        r"elimin\w*|borr\w*|supprim\w*|effac\w*|l[öo]sch\w*|"
        r"entfern\w*|apag\w*|droit\s+à\s+l['’]oubli|"
        r"gdpr|right\s+to\s+be\s+forgotten)\b",
        re.IGNORECASE,
    )
    non_deletion_request = re.compile(
        r"\b(?:send me (?:a )?copy|download|export|change|update|correct|"
        r"unsubscribe|opt[ -]?out|newsletter|marketing emails?|"
        r"order status|track (?:my )?order|login help|password reset)\b",
        re.IGNORECASE,
    )

    if non_deletion_request.search(text) and not explicit_deletion.search(text):
        return False
    return True


def audit_case(
    case_row: Dict[str, Any],
    identity: ResolvedIdentity,
    conn: sqlite3.Connection,
) -> Tuple[str, List[AuditStep]]:
    if not is_deletion_request(str(case_row.get("request_text", ""))):
        return "NOT_APPLICABLE", []

    cutoff = _time_key(case_row.get("audit_at"))
    requested = _time_key(case_row.get("requested_at"))
    manifest = [
        (str(file_id), str(path), str(origin or ""), _time_key(captured_at))
        for file_id, path, origin, captured_at in conn.execute(
            "SELECT file_id,file_path,origin,captured_at FROM evidence_files"
        )
        if file_id and _time_key(captured_at) <= cutoff
    ]
    sql_manifest = [
        entry for entry in manifest
        if Path(entry[1]).suffix.casefold() == ".sql"
    ]
    latest_sql = max(
        sql_manifest,
        key=lambda entry: (entry[3], entry[0]),
        default=None,
    )

    def infer_system(
        table_name: str, resource_id: str, record: Dict[str, Any]
    ) -> str:
        explicit = next(
            (
                record.get(key)
                for key in ("system_id", "source_system", "system")
                if record.get(key) and str(record[key]).strip()
            ),
            None,
        )
        if explicit:
            return str(explicit).strip()

        value = f"{table_name} {resource_id}".casefold()
        if "analytics_" in value or "telemetry" in value:
            return "analytics_platform"
        if "search_" in value:
            return "search_service"
        if "support_" in value:
            return "support_platform"
        if "audit_record_" in value or "security_" in value:
            return "security_service"
        if "backup_" in value:
            return "backup_service"
        if "data_flow_" in value:
            return "data_sync_service"
        return "account_service"

    def evidence_for(resource_id: str, system_id: str) -> str:
        resource_key = resource_id.casefold()
        system_terms = {
            "account_service": ("account", "customer", "profile"),
            "analytics_platform": ("analytics", "telemetry"),
            "search_service": ("search", "index"),
            "support_platform": ("support",),
            "security_service": ("security", "audit"),
            "backup_service": ("backup",),
            "data_sync_service": ("sync", "data_flow"),
        }.get(system_id.casefold(), (system_id.casefold(),))

        resource_matches = [
            (captured_at, file_id)
            for file_id, path, origin, captured_at in manifest
            if resource_key in f"{path} {origin}".casefold()
        ]
        if resource_matches:
            return max(resource_matches)[1]

        system_matches = [
            (captured_at, file_id)
            for file_id, path, origin, captured_at in manifest
            if any(
                term in f"{path} {origin}".casefold()
                for term in system_terms
            )
        ]
        if system_matches:
            return max(system_matches)[1]
        return latest_sql[0] if latest_sql else ""

    activity_fields = (
        "activity_id", "event_time", "event_type", "source_system",
        "target_system", "resource_id", "reported_result", "details",
    )
    events = []
    for values in conn.execute(
        "SELECT activity_id,event_time,event_type,source_system,target_system,"
        "resource_id,reported_result,details FROM system_activity "
        "WHERE event_time <= ? ORDER BY event_time,activity_id",
        (case_row.get("audit_at", ""),),
    ):
        event = dict(zip(activity_fields, values))
        if _strict_activity_matches(event, identity):
            events.append(event)

    disabled = {
        (event.get("resource_id") or "", event.get("source_system") or "")
        for event in events
        if event.get("event_type") == "DISABLE_DATA_FLOW"
    }
    blocked = {
        event.get("resource_id") or ""
        for event in events
        if event.get("event_type") == "BLOCK_RESTORE"
    }

    findings: List[Tuple[AuditStep, Optional[str]]] = []
    for event in events:
        event_type = event.get("event_type")
        resource_id = str(event.get("resource_id") or "")
        system_id = str(event.get("source_system") or "")
        if not system_id or system_id == "unknown_system":
            system_id = infer_system("", resource_id, {})
        activity_id = str(event.get("activity_id") or "")
        if not activity_id:
            continue

        event_time = _time_key(event.get("event_time"))
        if (
            event_type in {
                "SYNC_RECORD", "INDEX_RECORD", "UPDATE_RECORD", "EXPORT_DATA"
            }
            and requested < event_time
            and event.get("reported_result") == "SUCCESS"
            and (resource_id, system_id) not in disabled
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_ACTIVE_DATA_FLOW", "ACTIVE", activity_id,
                    ),
                    None,
                )
            )
        elif (
            event_type in {"BACKUP_SNAPSHOT", "RESTORE_BACKUP"}
            and resource_id not in blocked
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_RESTORE_RISK", "ACTIVE", activity_id,
                    ),
                    None,
                )
            )

    registry_exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' "
        "AND name='_northstar_snapshot_tables'"
    ).fetchone()
    snapshot_tables = (
        {
            row[0]
            for row in conn.execute(
                "SELECT table_name FROM _northstar_snapshot_tables"
            )
        }
        if registry_exists
        else set()
    )

    snapshots_by_source: Dict[str, Tuple[str, str, str]] = {}
    for table in snapshot_tables:
        match = re.match(r"(.+?)__(.+)", table)
        if not match:
            continue
        prefix, source_table = match.groups()
        source_file = next(
            (
                entry for entry in manifest
                if Path(entry[1]).stem.casefold() == prefix.casefold()
            ),
            None,
        )
        if not source_file:
            continue
        key = source_table.casefold()
        previous = snapshots_by_source.get(key)
        candidate = (source_file[3], source_file[0], table)
        if previous is None or candidate[:2] > previous[:2]:
            snapshots_by_source[key] = candidate

    findings_by_key = {
        (step.operation, step.system_id, step.resource_id, step.evidence_id):
        (step, treatment)
        for step, treatment in findings
    }

    for _source_name, (_captured_at, file_id, table) in sorted(
        snapshots_by_source.items()
    ):
        source_table = table.split("__", 1)[-1].casefold()
        if any(word in source_table for word in ("tombstone", "account")):
            category = "tombstone"
        elif any(word in source_table for word in ("analytics", "telemetry")):
            category = "analytics"
        elif any(
            word in source_table
            for word in (
                "profile", "search", "cache", "export", "support",
                "customer_data",
            )
        ):
            category = "delete"
        else:
            continue

        columns = [
            row[1]
            for row in conn.execute(f'PRAGMA table_info("{table}")')
        ]
        escaped_table = table.replace('"', '""')
        for values in conn.execute(f'SELECT * FROM "{escaped_table}"'):
            record = dict(zip(columns, values))
            if not _strict_row_matches_subject(record, identity):
                continue

            resource_id = str(
                record.get("resource_id")
                or record.get("record_id")
                or record.get("id")
                or record.get("account_id")
                or record.get("user_id")
                or table
            )
            system_id = infer_system(table, resource_id, record)
            row_text = _row_values(record)

            if category == "tombstone":
                pii_columns = {
                    "name", "email", "email_address", "phone", "phone_number",
                    "email_hash", "email_sha256",
                }
                direct_values = {
                    str(record[column]).strip().casefold()
                    for column in columns
                    if column.casefold() in pii_columns and record.get(column)
                }
                prohibited_values = (
                    {value.casefold() for value in identity.emails}
                    | {value.casefold() for value in identity.phones}
                    | {value.casefold() for value in identity.names}
                    | {value.casefold() for value in identity.email_hashes}
                )
                if direct_values & prohibited_values:
                    finding = AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_EXPOSED_PII", "PRESENT", file_id,
                    )
                    findings_by_key[
                        (
                            finding.operation, finding.system_id,
                            finding.resource_id, finding.evidence_id,
                        )
                    ] = (finding, "REDACT")
            elif category == "analytics":
                finding = AuditStep(
                    "FINDING", system_id, resource_id,
                    "REPORT_EXPOSED_PII", "PRESENT", file_id,
                )
                findings_by_key[
                    (
                        finding.operation, finding.system_id,
                        finding.resource_id, finding.evidence_id,
                    )
                ] = (finding, "ANONYMIZE")
            else:
                finding = AuditStep(
                    "FINDING", system_id, resource_id,
                    "REPORT_REMAINING_RECORD", "PRESENT", file_id,
                )
                findings_by_key[
                    (
                        finding.operation, finding.system_id,
                        finding.resource_id, finding.evidence_id,
                    )
                ] = (finding, "DELETE")

    valid_evidence = {
        str(row[0])
        for row in conn.execute(
            "SELECT file_id FROM evidence_files WHERE file_id IS NOT NULL"
        )
    } | {
        str(row[0])
        for row in conn.execute(
            "SELECT activity_id FROM system_activity WHERE activity_id IS NOT NULL"
        )
    }
    findings = [
        (step, treatment)
        for step, treatment in findings_by_key.values()
        if step.evidence_id and step.evidence_id in valid_evidence
        and step.system_id and step.system_id != "unknown_system"
    ]

    primary_user = next(iter(sorted(identity.user_ids)), "")
    suffix = primary_user.removeprefix("user_")
    primary_account = next(
        (
            resource
            for resource in identity.linked_resources
            if resource.casefold().startswith("account_")
        ),
        f"account_{suffix.zfill(3)}" if suffix.isdigit()
        else f"account_{suffix}",
    )

    if findings:
        account_has_finding = any(
            step.resource_id == primary_account for step, _ in findings
        )
        retained_verifications = (
            []
            if account_has_finding
            else [
                AuditStep(
                    "VERIFICATION", "account_service", primary_account,
                    "VERIFY_RECORD_ABSENT", "ABSENT", "",
                )
            ]
        )
        return "INCOMPLETE", expand_findings_to_plan(
            findings, retained_verifications=retained_verifications
        )

    verifications: List[AuditStep] = []
    account_evidence = evidence_for(primary_account, "account_service")
    if account_evidence:
        verifications.append(
            AuditStep(
                "VERIFICATION", "account_service", primary_account,
                "VERIFY_RECORD_ABSENT", "ABSENT", account_evidence,
            )
        )

    for resource_id in sorted(identity.linked_resources):
        resource_key = resource_id.casefold()
        if resource_key.startswith("audit_record_"):
            system_id, operation, state = (
                "security_service", "VERIFY_RECORD_PRESENT", "PRESENT"
            )
        elif resource_key.startswith("analytics_"):
            system_id, operation, state = (
                "analytics_platform",
                "VERIFY_RECORD_ANONYMIZED",
                "ANONYMIZED",
            )
        else:
            continue

        evidence_id = evidence_for(resource_id, system_id)
        if evidence_id:
            verifications.append(
                AuditStep(
                    "VERIFICATION", system_id, resource_id,
                    operation, state, evidence_id,
                )
            )

    if not verifications:
        return "INCOMPLETE", []
    return "COMPLETE", sorted(
        verifications,
        key=lambda step: (step.system_id, step.resource_id),
    )

def _strict_row_matches_subject(
