        event_time = _time_key(event.get("event_time"))
        if (
            event_type in {
                "SYNC_RECORD", "INDEX_RECORD", "UPDATE_RECORD", "EXPORT_DATA"
            }
            and requested < event_time
            and event.get("reported_result") == "SUCCESS"
            and (resource_id, system_id) not in disabled
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_ACTIVE_DATA_FLOW", "ACTIVE", activity_id,
                    ),
                    None,
                )
            )
        elif (
            event_type in {"BACKUP_SNAPSHOT", "RESTORE_BACKUP"}
            and resource_id not in blocked
        ):
            findings.append(
                (
                    AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_RESTORE_RISK", "ACTIVE", activity_id,
                    ),
                    None,
                )
            )

    registry_exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' "
        "AND name='_northstar_snapshot_tables'"
    ).fetchone()
    snapshot_tables = (
        {
            row[0]
            for row in conn.execute(
                "SELECT table_name FROM _northstar_snapshot_tables"
            )
        }
        if registry_exists
        else set()
    )

    snapshots_by_source: Dict[str, Tuple[str, str, str]] = {}
    for table in snapshot_tables:
        match = re.match(r"(.+?)__(.+)", table)
        if not match:
            continue
        prefix, source_table = match.groups()
        source_file = next(
            (
                entry for entry in manifest
                if Path(entry[1]).stem.casefold() == prefix.casefold()
            ),
            None,
        )
        if not source_file:
            continue
        key = source_table.casefold()
        previous = snapshots_by_source.get(key)
        candidate = (source_file[3], source_file[0], table)
        if previous is None or candidate[:2] > previous[:2]:
            snapshots_by_source[key] = candidate

    findings_by_key = {
        (step.operation, step.system_id, step.resource_id, step.evidence_id):
        (step, treatment)
        for step, treatment in findings
    }

    for _source_name, (_captured_at, file_id, table) in sorted(
        snapshots_by_source.items()
    ):
        source_table = table.split("__", 1)[-1].casefold()
        if any(word in source_table for word in ("tombstone", "account")):
            category = "tombstone"
        elif any(word in source_table for word in ("analytics", "telemetry")):
            category = "analytics"
        elif any(
            word in source_table
            for word in (
                "profile", "search", "cache", "export", "support",
                "customer_data",
            )
        ):
            category = "delete"
        else:
            continue

        columns = [
            row[1]
            for row in conn.execute(f'PRAGMA table_info("{table}")')
        ]
        escaped_table = table.replace('"', '""')
        for values in conn.execute(f'SELECT * FROM "{escaped_table}"'):
            record = dict(zip(columns, values))
            if not _strict_row_matches_subject(record, identity):
                continue

            resource_id = str(
                record.get("resource_id")
                or record.get("record_id")
                or record.get("id")
                or record.get("account_id")
                or record.get("user_id")
                or table
            )
            system_id = infer_system(table, resource_id, record)
            row_text = _row_values(record)

            if category == "tombstone":
                pii_columns = {
                    "name", "email", "email_address", "phone", "phone_number",
                    "email_hash", "email_sha256",
                }
                direct_values = {
                    str(record[column]).strip().casefold()
                    for column in columns
                    if column.casefold() in pii_columns and record.get(column)
                }
                prohibited_values = (
                    {value.casefold() for value in identity.emails}
                    | {value.casefold() for value in identity.phones}
                    | {value.casefold() for value in identity.names}
                    | {value.casefold() for value in identity.email_hashes}
                )
                if direct_values & prohibited_values:
                    finding = AuditStep(
                        "FINDING", system_id, resource_id,
                        "REPORT_EXPOSED_PII", "PRESENT", file_id,
                    )
                    findings_by_key[
                        (
                            finding.operation, finding.system_id,
                            finding.resource_id, finding.evidence_id,
                        )
                    ] = (finding, "REDACT")
            elif category == "analytics":
                finding = AuditStep(
                    "FINDING", system_id, resource_id,
                    "REPORT_EXPOSED_PII", "PRESENT", file_id,
                )
                findings_by_key[
                    (
                        finding.operation, finding.system_id,
                        finding.resource_id, finding.evidence_id,
                    )
                ] = (finding, "ANONYMIZE")
            else:
                finding = AuditStep(
                    "FINDING", system_id, resource_id,
                    "REPORT_REMAINING_RECORD", "PRESENT", file_id,
                )
                findings_by_key[
                    (
                        finding.operation, finding.system_id,
                        finding.resource_id, finding.evidence_id,
                    )
                ] = (finding, "DELETE")

    valid_evidence = {
        str(row[0])
        for row in conn.execute(
            "SELECT file_id FROM evidence_files WHERE file_id IS NOT NULL"
        )
    } | {
        str(row[0])
        for row in conn.execute(
            "SELECT activity_id FROM system_activity WHERE activity_id IS NOT NULL"
        )
    }
    findings = [
        (step, treatment)
        for step, treatment in findings_by_key.values()
        if step.evidence_id and step.evidence_id in valid_evidence
        and step.system_id and step.system_id != "unknown_system"
    ]

    primary_user = next(iter(sorted(identity.user_ids)), "")
    suffix = primary_user.removeprefix("user_")
    primary_account = next(
        (
            resource
            for resource in identity.linked_resources
            if resource.casefold().startswith("account_")
        ),
        f"account_{suffix.zfill(3)}" if suffix.isdigit()
        else f"account_{suffix}",
    )

    if findings:
        account_has_finding = any(
            step.resource_id == primary_account for step, _ in findings
        )
        retained_verifications = (
            []
            if account_has_finding
            else [
                AuditStep(
                    "VERIFICATION", "account_service", primary_account,
                    "VERIFY_RECORD_ABSENT", "ABSENT", "",
                )
            ]
        )
        return "INCOMPLETE", expand_findings_to_plan(
            findings, retained_verifications=retained_verifications
        )

    verifications: List[AuditStep] = []
    account_evidence = evidence_for(primary_account, "account_service")
    if account_evidence:
        verifications.append(
            AuditStep(
                "VERIFICATION", "account_service", primary_account,
                "VERIFY_RECORD_ABSENT", "ABSENT", account_evidence,
            )
        )

    for resource_id in sorted(identity.linked_resources):
        resource_key = resource_id.casefold()
        if resource_key.startswith("audit_record_"):
            system_id, operation, state = (
                "security_service", "VERIFY_RECORD_PRESENT", "PRESENT"
            )
        elif resource_key.startswith("analytics_"):
            system_id, operation, state = (
                "analytics_platform",
                "VERIFY_RECORD_ANONYMIZED",
                "ANONYMIZED",
            )
        else:
            continue

        evidence_id = evidence_for(resource_id, system_id)
        if evidence_id:
            verifications.append(
                AuditStep(
                    "VERIFICATION", system_id, resource_id,
                    operation, state, evidence_id,
                )
            )

    if not verifications:
        return "INCOMPLETE", []
    return "COMPLETE", sorted(
        verifications,
        key=lambda step: (step.system_id, step.resource_id),
    )

