                    )
                    for token in subject_tokens
                ):
                    matched_indexes.append(index)

            for index in matched_indexes:
                line = lines[index]
                trace_match = re.search(
                    r"\b(?:trace_id|correlation_id|requestId|request_id)=?['\"]?"
                    r"([A-Za-z0-9-]+)",
