def resolve_identity(case_email: str, conn: sqlite3.Connection) -> ResolvedIdentity:
    """Resolve the identity graph and attach evidence-indexed resources."""
    identity = _resolve_identity_without_evidence(case_email, conn)
    identity.evidence_resources = []

    table_exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='evidence_records'"
    ).fetchone()
    if not table_exists:
        return identity

    columns = {
        row[1].casefold()
        for row in conn.execute('PRAGMA table_info("evidence_records")')
    }
    required = {
        "file_id", "captured_at", "system_id", "resource_id",
        "verified_state", "email", "user_id",
    }
    if not required.issubset(columns):
        return identity

    clauses: List[str] = []
    params: List[str] = []
    emails = sorted(value for value in identity.emails if value)
    user_ids = sorted(value for value in identity.user_ids if value)

    if emails:
        clauses.append(
            "LOWER(email) IN (" + ",".join("?" for _ in emails) + ")"
        )
        params.extend(value.casefold() for value in emails)
    if user_ids:
        clauses.append(
            "user_id IN (" + ",".join("?" for _ in user_ids) + ")"
        )
        params.extend(user_ids)
    if not clauses:
        return identity

    for file_id, captured_at, system_id, resource_id, verified_state in conn.execute(
        "SELECT file_id,captured_at,system_id,resource_id,verified_state "
        "FROM evidence_records WHERE " + " OR ".join(clauses) +
        " ORDER BY captured_at,file_id,resource_id",
        params,
    ):
        resource = str(resource_id or "").strip()
        if not resource:
            continue
        identity.evidence_resources.append({
            "file_id": str(file_id or "").strip(),
            "captured_at": str(captured_at or "").strip(),
            "system_id": str(system_id or "").strip(),
            "resource_id": resource,
            "state": str(verified_state or "").strip().upper(),
        })
        identity.linked_resources.add(resource)

    return identity


def audit_case(
    case_row: Dict[str, Any],
    identity: ResolvedIdentity,
    conn: sqlite3.Connection,
) -> Tuple[str, List[AuditStep]]:
    """Audit a deletion request using temporal evidence and indexed records."""
    if not is_deletion_request(str(case_row.get("request_text", ""))):
        return "NOT_APPLICABLE", []

    status, steps = _audit_case_without_evidence_records(case_row, identity, conn)
    cutoff = _time_key(case_row.get("audit_at"))
    evidence_rows = list(getattr(identity, "evidence_resources", []))

    if not evidence_rows:
        table_exists = conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='evidence_records'"
        ).fetchone()
        if table_exists:
            columns = {
                row[1].casefold()
                for row in conn.execute('PRAGMA table_info("evidence_records")')
            }
            required = {
                "file_id", "captured_at", "system_id", "resource_id",
                "verified_state", "email", "user_id",
            }
            if required.issubset(columns):
                clauses: List[str] = []
                params: List[str] = []
                emails = sorted(value for value in identity.emails if value)
                user_ids = sorted(value for value in identity.user_ids if value)
                if emails:
                    clauses.append(
                        "LOWER(email) IN (" + ",".join("?" for _ in emails) + ")"
                    )
                    params.extend(value.casefold() for value in emails)
                if user_ids:
                    clauses.append(
                        "user_id IN (" + ",".join("?" for _ in user_ids) + ")"
                    )
                    params.extend(user_ids)
                if clauses:
                    evidence_rows = [
                        {
                            "file_id": str(file_id or "").strip(),
                            "captured_at": str(captured_at or "").strip(),
                            "system_id": str(system_id or "").strip(),
                            "resource_id": str(resource_id or "").strip(),
                            "state": str(verified_state or "").strip().upper(),
                        }
                        for file_id, captured_at, system_id, resource_id, verified_state
                        in conn.execute(
                            "SELECT file_id,captured_at,system_id,resource_id,verified_state "
                            "FROM evidence_records WHERE " + " OR ".join(clauses),
                            params,
                        )
                    ]

    state_map = {
        "ABSENT": ("VERIFY_RECORD_ABSENT", "ABSENT"),
        "PRESENT": ("VERIFY_RECORD_PRESENT", "PRESENT"),
        "ANONYMIZED": ("VERIFY_RECORD_ANONYMIZED", "ANONYMIZED"),
        "REDACTED": ("VERIFY_RECORD_REDACTED", "REDACTED"),
    }
    eligible: Dict[Tuple[str, str], Dict[str, str]] = {}
    for record in evidence_rows:
        if _time_key(record.get("captured_at")) > cutoff:
            continue
        resource_id = str(record.get("resource_id") or "").strip()
        system_id = str(record.get("system_id") or "").strip()
        file_id = str(record.get("file_id") or "").strip()
        state = str(record.get("state") or "").strip().upper()
        if resource_id and system_id and file_id and state in state_map:
            eligible[(system_id, resource_id)] = {
                "file_id": file_id,
                "state": state,
            }

    if status == "COMPLETE" and eligible:
        valid_file_ids = {
            str(row[0])
            for row in conn.execute(
                "SELECT file_id FROM evidence_files WHERE file_id IS NOT NULL"
            )
        }
        verifications: List[AuditStep] = []
        for (system_id, resource_id), record in eligible.items():
            if record["file_id"] not in valid_file_ids:
                continue
            operation, state = state_map[record["state"]]
            verifications.append(AuditStep(
                phase="VERIFICATION",
                system_id=system_id,
                resource_id=resource_id,
                operation=operation,
                state=state,
                evidence_id=record["file_id"],
            ))
        if verifications:
            return "COMPLETE", sorted(
                verifications,
                key=lambda step: (step.system_id, step.resource_id),
            )

    if status == "INCOMPLETE":
        finding_resources = {
            (step.system_id, step.resource_id)
            for step in steps
            if step.phase == "FINDING"
        }
        verifications = [
            step for step in steps if step.phase == "VERIFICATION"
        ]
        for (system_id, resource_id), record in eligible.items():
            if (system_id, resource_id) in finding_resources:
                continue
            operation, state = state_map[record["state"]]
            verifications.append(AuditStep(
                phase="VERIFICATION",
                system_id=system_id,
                resource_id=resource_id,
                operation=operation,
                state=state,
                evidence_id="",
            ))
        steps = [
            step for step in steps if step.phase != "VERIFICATION"
        ] + verifications
        return status, steps

    return status, steps


def build_steps_json(deletion_status: str, raw_steps: List[AuditStep]) -> str:
    """Validate, deduplicate, canonically sort, number, and serialize audit steps."""
    if deletion_status == "NOT_APPLICABLE":
        return "[]"
    if deletion_status not in ("COMPLETE", "INCOMPLETE"):
        raise ValueError(f"Invalid deletion_status: {deletion_status}")

    normalized: Dict[Tuple[str, str, str, str], AuditStep] = {}
    for step in raw_steps:
        expected_state = step.validated_state()

        if deletion_status == "COMPLETE":
            if step.phase != "VERIFICATION":
                raise ValueError("COMPLETE cases may only contain VERIFICATION steps.")
            if not step.evidence_id:
                raise ValueError(
                    f"COMPLETE verification step on {step.system_id}/{step.resource_id} "
                    "must cite a file_id, activity_id, or audit_id."
                )
            evidence_id = step.evidence_id
        elif step.phase == "FINDING":
            if not step.evidence_id:
                raise ValueError(
                    f"INCOMPLETE finding step on {step.system_id}/{step.resource_id} "
                    "must cite a file_id, activity_id, or audit_id."
                )
            evidence_id = step.evidence_id
        else:
            evidence_id = ""

        clean_step = AuditStep(
            phase=step.phase,
            system_id=step.system_id,
            resource_id=step.resource_id,
            operation=step.operation,
            state=expected_state,
            evidence_id=evidence_id,
        )
        key = (
            clean_step.phase,
            clean_step.operation,
            clean_step.system_id,
            clean_step.resource_id,
        )
        normalized[key] = clean_step

    sorted_steps = sorted(
        normalized.values(),
        key=lambda step: (
            PHASE_ORDER[step.phase],
            step.system_id,
            step.resource_id,
            step.operation,
            step.evidence_id,
        ),
    )
    payload = [
        {
            "step_no": index,
            "phase": step.phase,
            "system_id": step.system_id,
            "resource_id": step.resource_id,
            "operation": step.operation,
            "state": step.state,
            "evidence_id": step.evidence_id,
        }
        for index, step in enumerate(sorted_steps, start=1)
    ]
    return json.dumps(payload, separators=(",", ":"))

def resolve_identity(case_email: str, conn: sqlite3.Connection) -> ResolvedIdentity:
    """Resolve the identity graph and attach evidence-indexed resources."""
