    user_ids = sorted(value for value in identity.user_ids if value)

    if emails:
        clauses.append(
            "LOWER(email) IN (" + ",".join("?" for _ in emails) + ")"
        )
        params.extend(value.casefold() for value in emails)
    if user_ids:
        clauses.append(
            "user_id IN (" + ",".join("?" for _ in user_ids) + ")"
        )
        params.extend(user_ids)
    if not clauses:
        return identity

    for file_id, captured_at, system_id, resource_id, verified_state in conn.execute(
