            operation, state = state_map[record["state"]]
            verified.append(AuditStep(
                "VERIFICATION", system, resource, operation, state, record["file_id"]
            ))
        if verified:
            return "COMPLETE", sorted(verified, key=lambda step: (step.system_id, step.resource_id))

    if status == "INCOMPLETE":
        # Preserve generated finding/remediation steps while incorporating the
