def resolve_identity(case_email: str, conn: sqlite3.Connection) -> ResolvedIdentity:
    """Resolve the identity graph and attach evidence-indexed resources."""
    identity = _resolve_identity_without_evidence(case_email, conn)
    identity.evidence_resources = []
    exists = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='evidence_records'"
    ).fetchone()
    if not exists:
        return identity

    columns = {row[1].casefold() for row in conn.execute('PRAGMA table_info("evidence_records")')}
    required = {"file_id", "captured_at", "system_id", "resource_id", "verified_state", "email", "user_id"}
    if not required.issubset(columns):
        return identity

    emails = sorted(value for value in identity.emails if value)
    user_ids = sorted(value for value in identity.user_ids if value)
    clauses: List[str] = []
    params: List[str] = []
    if emails:
        clauses.append("LOWER(email) IN (" + ",".join("?" for _ in emails) + ")")
        params.extend(value.casefold() for value in emails)
    if user_ids:
        clauses.append("user_id IN (" + ",".join("?" for _ in user_ids) + ")")
        params.extend(user_ids)
    if not clauses:
        return identity

    for file_id, captured_at, system_id, resource_id, verified_state in conn.execute(
        "SELECT file_id,captured_at,system_id,resource_id,verified_state "
        "FROM evidence_records WHERE " + " OR ".join(clauses) +
        " ORDER BY captured_at,file_id,resource_id",
        params,
    ):
        if not resource_id:
            continue
        resource_id = str(resource_id).strip()
        if not resource_id:
            continue
        record = {
            "file_id": str(file_id or ""),
            "captured_at": str(captured_at or ""),
            "system_id": str(system_id or ""),
            "resource_id": resource_id,
            "state": str(verified_state or "").strip().upper(),
        }
        identity.evidence_resources.append(record)
        identity.linked_resources.add(resource_id)
    return identity


