                    matched_req = req
                    break
                try:
                    t_act = datetime.fromisoformat(act_time.replace("Z", "+00:00"))
                    t_rep = datetime.fromisoformat(rep_at.replace("Z", "+00:00"))
                    if abs((t_act - t_rep).total_seconds()) <= 7200:
                        matched_req = req
                        break
                except Exception:
                    pass
        if matched_req:
            email = matched_req["email"]
            user_row = c.execute("SELECT user_id FROM user_identities WHERE email = ?", (email,)).fetchone()
            user_id = user_row[0] if user_row else matched_req.get("user_id")
            c.execute("UPDATE evidence_records SET user_id = ?, email = ? WHERE resource_id = ?", (user_id, email, res_id))
    conn.commit()

#!/usr/bin/env python3
"""
Zero-token local evidence indexer for Northstar Shop Deletion Audit dataset.
Correlates trace events across logs and records into SQLite cache/northstar.db.
"""

from __future__ import annotations

import csv
import json
import re
import sqlite3
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

KV_REGEX = re.compile(r'(\w+)=(?:"([^"]*)"|(\S+))')


def _clean_str(val: Any) -> Optional[str]:
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() in ("null", "none"):
        return None
    return s


def _parse_iso_ts(ts_str: Any) -> Optional[datetime]:
    if not ts_str:
        return None
    s = str(ts_str).strip()
    if not s or s.lower() in ("null", "none"):
        return None
    try:
        return datetime.fromisoformat(s.replace("Z", "+00:00"))
    except Exception:
        return None


def index_unstructured_evidence(
    evidence_dir: Path = Path("dataset/evidence"),
    conn: Optional[sqlite3.Connection] = None,
) -> None:
    """
    Parse files in logs/ and records/, perform two-pass trace correlation,
    correlate anonymized analytics from system_activity, and populate evidence_records.
    """
    evidence_path = Path(evidence_dir)
    close_conn = False

    if conn is None:
        db_path = Path("cache/northstar.db")
        db_path.parent.mkdir(parents=True, exist_ok=True)
        conn = sqlite3.connect(db_path)
        close_conn = True

    try:
        # 1. Table Schema
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS evidence_records (
                file_id TEXT,
                captured_at TEXT,
                system_id TEXT,
                resource_id TEXT PRIMARY KEY,
                verified_state TEXT,       -- 'ABSENT', 'PRESENT', 'ANONYMIZED', 'REDACTED'
                user_id TEXT,
                email TEXT
            );
            """
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ev_res ON evidence_records(resource_id);")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ev_user ON evidence_records(user_id);")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ev_email ON evidence_records(email);")

        # Load file metadata: filename -> (file_id, captured_at)
        file_meta: Dict[str, Tuple[str, str]] = {}
        try:
            cur = conn.execute("SELECT file_id, file_path, captured_at FROM evidence_files")
            for row in cur.fetchall():
                if row[1]:
                    file_meta[Path(row[1]).name] = (row[0] or "", row[2] or "")
        except Exception:
            pass

        ef_csv_candidates = [
            evidence_path.parent / "evidence_files.csv",
            Path("dataset/evidence_files.csv"),
        ]
        for ef_csv in ef_csv_candidates:
            if ef_csv.is_file():
                try:
                    with ef_csv.open("r", encoding="utf-8-sig", newline="") as f:
                        for row in csv.DictReader(f):
                            fp = row.get("file_path")
                            if fp:
                                file_meta[Path(fp).name] = (
                                    row.get("file_id", ""),
                                    row.get("captured_at", ""),
                                )
                    break
                except Exception:
                    pass

        # Load identity resolution mappings
        email_to_user: Dict[str, str] = {}
        user_to_email: Dict[str, str] = {}
        try:
            for r in conn.execute(
                "SELECT user_id, email FROM user_identities WHERE user_id IS NOT NULL AND email IS NOT NULL"
            ).fetchall():
                if r[0] and r[1]:
                    email_to_user[r[1].lower().strip()] = r[0].strip()
                    user_to_email[r[0].strip()] = r[1].strip()
        except Exception:
            pass

        for candidate in [
            evidence_path.parent / "user_identities.csv",
            Path("dataset/user_identities.csv"),
        ]:
            if candidate.is_file():
                try:
                    with candidate.open("r", encoding="utf-8-sig", newline="") as f:
                        for row in csv.DictReader(f):
                            uid = row.get("user_id")
                            eml = row.get("email")
                            if uid and eml:
                                email_to_user[eml.lower().strip()] = uid.strip()
                                user_to_email[uid.strip()] = eml.strip()
                    break
                except Exception:
                    pass

        merged_records: Dict[str, Tuple[str, str, str, str, str, Optional[str], Optional[str]]] = {}

        def record_finding(
            fid: str,
            cap: str,
            sys_id: Optional[str],
            res_id: str,
            state: Optional[str],
            uid: Optional[str],
            eml: Optional[str],
        ) -> None:
            if not res_id:
                return
            sys_id = _clean_str(sys_id) or ""
            uid = _clean_str(uid)
            eml = _clean_str(eml)

            if eml and "@" not in eml:
                if not uid and eml.startswith("user_"):
                    uid = eml
                    eml = None

            if eml and not uid:
                uid = email_to_user.get(eml.lower())
            if uid and not eml:
                eml = user_to_email.get(uid)

            if res_id in merged_records:
                old_fid, old_cap, old_sys, _, old_state, old_uid, old_eml = merged_records[res_id]
                fid = fid or old_fid
                cap = cap or old_cap
                sys_id = sys_id or old_sys
                uid = uid or old_uid
                eml = eml or old_eml
                state = state or old_state

            merged_records[res_id] = (
                fid or "",
                cap or "",
                sys_id,
                res_id,
                state or "PRESENT",
                uid,
                eml,
            )

        # 2. TWO-PASS TRACE CORRELATION FOR LOGS
        logs_dir = evidence_path / "logs"
        if logs_dir.is_dir():
            for log_file in sorted(logs_dir.glob("*.log")):
                fid, cap = file_meta.get(log_file.name, ("", ""))
                trace_groups: Dict[str, List[Dict[str, Any]]] = {}

                try:
                    with log_file.open("r", encoding="utf-8", errors="ignore") as f:
                        for line_idx, line in enumerate(f):
                            line = line.strip()
                            if not line:
                                continue

                            entry: Dict[str, Any] = {}
                            j_start = line.find("{")
                            if j_start != -1 and line.endswith("}"):
                                try:
                                    entry = json.loads(line[j_start:])
                                except Exception:
                                    pass
                            elif "=" in line:
                                for m in KV_REGEX.findall(line):
                                    k = m[0]
                                    v = m[1] if m[1] != "" else m[2]
                                    entry[k] = v

                            trace_id = entry.get("trace_id") or entry.get("requestId")
                            if not trace_id:
                                trace_id = f"__no_trace__{log_file.stem}_{line_idx}"

                            trace_groups.setdefault(str(trace_id), []).append(entry)
                except Exception:
                    continue

                for trace_id, entries in trace_groups.items():
                    # Pass 1: Extract Identifiers per trace
                    trace_email: Optional[str] = None
                    trace_user_id: Optional[str] = None

                    for entry in entries:
                        for k in (
                            "lookup_key",
                            "subject_ref",
                            "subject_reference",
                            "email",
                            "customer_email",
                            "requester_email",
                            "match_key",
                            "correlation_key",
                        ):
                            val = entry.get(k)
                            if val is not None:
                                val_str = str(val).strip()
                                if not val_str or val_str.lower() in ("null", "none"):
                                    continue
                                if "@" in val_str and not trace_email:
                                    trace_email = val_str
                                if val_str.startswith("user_") and not trace_user_id:
                                    trace_user_id = val_str

                    if trace_email and not trace_user_id:
                        trace_user_id = email_to_user.get(trace_email.lower())
                    if trace_user_id and not trace_email:
                        trace_email = user_to_email.get(trace_user_id)

                    # Pass 2: Extract Resources and assign identifiers
                    for entry in entries:
                        res_id = _clean_str(entry.get("resource_id"))
                        if not res_id:
                            continue

                        sys_id = (
                            entry.get("service")
                            or entry.get("system")
                            or entry.get("system_id")
                            or entry.get("logger")
                        )
                        if sys_id:
                            sys_id = str(sys_id).strip()
                        else:
                            if res_id.startswith("analytics_"):
                                sys_id = "analytics_platform"
                            elif res_id.startswith("account_"):
                                sys_id = "account_service"
                            elif res_id.startswith("audit_record_"):
                                sys_id = "security_service"
                            elif res_id.startswith("search_"):
                                sys_id = "search_service"
                            elif res_id.startswith("support_"):
                                sys_id = "support_platform"
                            elif res_id.startswith("export_"):
                                sys_id = "export_service"
                            elif res_id.startswith("backup_"):
                                sys_id = "backup_service"
                            elif res_id.startswith("data_flow_"):
                                sys_id = "integration_service"

                        rows_val = str(entry.get("rows") if entry.get("rows") is not None else "").strip()
                        status_val = str(
                            entry.get("http_status") if entry.get("http_status") is not None else ""
                        ).strip()
                        event_val = str(entry.get("event") or "")
                        integrity_val = str(entry.get("integrity_check") or "").lower()
                        has_retention = (
                            entry.get("retention_until") is not None
                            and str(entry.get("retention_until")).lower() not in ("null", "none", "")
                        )

                        cust_ref = entry.get("customer_reference")
                        eml_val = entry.get("email")
                        cust_null = cust_ref is None or str(cust_ref).lower() in ("null", "none", "")
                        eml_null = eml_val is None or str(eml_val).lower() in ("null", "none", "")

                        # State mapping
                        if (
                            rows_val in ("0", "404")
                            or status_val == "404"
                            or ("profile_lookup_completed" in event_val and rows_val == "0")
                            or str(entry.get("result") or "").lower() in ("miss", "not_found")
                        ):
                            state = "ABSENT"
                        elif (
                            rows_val in ("1", "200")
                            or status_val == "200"
                            or integrity_val == "passed"
                            or has_retention
                            or str(entry.get("result") or "").lower() in ("hit", "found")
                            or event_val == "audit_record_read_completed"
                        ):
                            state = "PRESENT"
                        elif cust_null and eml_null:
                            state = "ANONYMIZED"
                        else:
                            state = "PRESENT"

                        # Assign identifiers
                        row_user = trace_user_id
                        row_email = trace_email

                        entry_user = (
                            entry.get("user_id")
                            or entry.get("subject_ref")
                            or entry.get("customer_reference")
                        )
                        if entry_user and str(entry_user).strip().startswith("user_"):
                            row_user = str(entry_user).strip()

                        entry_email = entry.get("email") or entry.get("lookup_key")
                        if entry_email and "@" in str(entry_email):
                            row_email = str(entry_email).strip()

                        if row_email and not row_user:
                            row_user = email_to_user.get(row_email.lower())
                        if row_user and not row_email:
                            row_email = user_to_email.get(row_user)

                        record_finding(fid, cap, sys_id, res_id, state, row_user, row_email)

        # 3. Process records directory (JSON and TXT)
        records_dir = evidence_path / "records"
        if records_dir.is_dir():
            for rec_file in sorted(records_dir.iterdir()):
                fid, cap = file_meta.get(rec_file.name, ("", ""))
                if rec_file.suffix == ".json":
                    try:
                        data = json.loads(rec_file.read_text(encoding="utf-8", errors="ignore"))
                        items = []
                        if isinstance(data, list):
                            items = data
                        elif isinstance(data, dict):
                            for key in ("records", "snapshots", "service_exports"):
                                if key in data and isinstance(data[key], list):
                                    items = data[key]
                                    break

                        for item in items:
                            if not isinstance(item, dict):
                                continue
                            res_id = _clean_str(item.get("resource_id"))
                            if not res_id:
                                continue

                            sys_id = item.get("system") or item.get("service") or item.get("system_id")
                            if not sys_id:
                                if res_id.startswith("analytics_"):
                                    sys_id = "analytics_platform"
                                elif res_id.startswith("account_"):
                                    sys_id = "account_service"
                                elif res_id.startswith("audit_record_"):
                                    sys_id = "security_service"
                                elif res_id.startswith("search_"):
                                    sys_id = "search_service"
                                elif res_id.startswith("support_"):
                                    sys_id = "support_platform"
                                elif res_id.startswith("export_"):
                                    sys_id = "export_service"
                                elif res_id.startswith("backup_"):
                                    sys_id = "backup_service"
                                elif res_id.startswith("data_flow_"):
                                    sys_id = "integration_service"

                            uid = item.get("user_id") or item.get("customer_reference") or item.get("subject_reference")
                            eml = (
                                item.get("email")
                                or item.get("owner_email")
                                or item.get("subject_reference")
                                or item.get("lookup_key")
                            )

                            res_val = str(item.get("result") or item.get("status") or "").upper()
                            if res_val in ("NOT_FOUND", "ABSENT", "MISS"):
                                state = "ABSENT"
                            elif (
                                not _clean_str(uid)
                                and not _clean_str(eml)
                                and not _clean_str(item.get("phone"))
                                and not _clean_str(item.get("email_hash"))
                            ):
                                state = "ANONYMIZED"
                            else:
                                state = "PRESENT"

                            record_finding(fid, cap, sys_id, res_id, state, uid, eml)
                    except Exception:
                        pass
                elif rec_file.suffix == ".txt":
                    try:
                        for line in rec_file.read_text(encoding="utf-8", errors="ignore").splitlines():
                            if "|" in line:
                                parts = [x.strip() for x in line.split("|")]
                                if len(parts) >= 5:
                                    line_sys = parts[1]
                                    line_res = parts[2]
                                    line_result = parts[4].upper()
                                    line_subj = parts[5] if len(parts) > 5 else None
                                    state = "ABSENT" if line_result == "NOT_FOUND" else "PRESENT"
                                    uid = line_subj if line_subj and line_subj.startswith("user_") else None
                                    eml = line_subj if line_subj and "@" in line_subj else None
                                    record_finding(fid, cap, line_sys, line_res, state, uid, eml)
                    except Exception:
                        pass

        # 4. Batch Inserts
        if merged_records:
            conn.executemany(
                """
                INSERT OR REPLACE INTO evidence_records (
                    file_id, captured_at, system_id, resource_id, verified_state, user_id, email
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                list(merged_records.values()),
            )
            conn.commit()
    correlate_anonymized_analytics(conn)

        # 5. CORRELATE ANONYMIZED ANALYTICS FROM system_activity
        # Load deletion requests with reported_at
        deletion_requests_list: List[Tuple[str, datetime]] = []

        try:
            for r in conn.execute(
                "SELECT email, reported_at FROM deletion_requests WHERE email IS NOT NULL AND reported_at IS NOT NULL"
            ).fetchall():
                t_dt = _parse_iso_ts(r[1])
                if r[0] and t_dt:
                    deletion_requests_list.append((r[0].strip(), t_dt))
        except Exception:
            pass

        for csv_name in ("sample_deletion_requests.csv", "deletion_requests.csv"):
            for candidate in [evidence_path.parent / csv_name, Path("dataset") / csv_name]:
                if candidate.is_file():
                    try:
                        with candidate.open("r", encoding="utf-8-sig", newline="") as f:
                            for row in csv.DictReader(f):
                                eml = row.get("email")
                                rep = row.get("reported_at")
                                if eml and rep:
                                    t_dt = _parse_iso_ts(rep)
                                    if t_dt:
                                        deletion_requests_list.append((eml.strip(), t_dt))
                        break
                    except Exception:
                        pass

        # Candidate rows: analytics_platform, ANONYMIZED, NULL or empty user_id/email
        candidates = conn.execute(
            """
            SELECT resource_id FROM evidence_records
            WHERE system_id = 'analytics_platform'
              AND verified_state = 'ANONYMIZED'
              AND (user_id IS NULL OR user_id = '' OR email IS NULL OR email = '')
            """
        ).fetchall()

        updates: List[Tuple[str, Optional[str], str]] = []

        for (res_id,) in candidates:
            event_time_str = None
            try:
                row = conn.execute(
                    "SELECT event_time FROM system_activity WHERE resource_id = ? AND event_type = 'ANONYMIZE_RECORD' LIMIT 1",
                    (res_id,),
                ).fetchone()
                if row and row[0]:
                    event_time_str = row[0]
            except Exception:
                pass

            if not event_time_str:
                for candidate in [
                    evidence_path.parent / "system_activity.csv",
                    Path("dataset/system_activity.csv"),
                ]:
                    if candidate.is_file():
                        try:
                            with candidate.open("r", encoding="utf-8-sig", newline="") as f:
                                for row in csv.DictReader(f):
                                    if (
                                        row.get("resource_id") == res_id
                                        and row.get("event_type") == "ANONYMIZE_RECORD"
                                    ):
                                        event_time_str = row.get("event_time")
                                        break
                            if event_time_str:
                                break
                        except Exception:
                            pass

            if not event_time_str:
                continue

            ev_dt = _parse_iso_ts(event_time_str)
            if not ev_dt:
                continue

            matched_email = None
            closest_diff = None
            for req_email, req_dt in deletion_requests_list:
                diff = abs((req_dt - ev_dt).total_seconds())
                if diff <= 900:  # within +/- 15 minutes
                    if closest_diff is None or diff < closest_diff:
                        closest_diff = diff
                        matched_email = req_email

            if matched_email:
                matched_user_id = email_to_user.get(matched_email.lower())
                updates.append((matched_email, matched_user_id, res_id))

        if updates:
            conn.executemany(
                """
                UPDATE evidence_records
                SET email = ?,
                    user_id = COALESCE(?, user_id)
                WHERE resource_id = ?
                """,
                updates,
