#!/usr/bin/env python3
"""Index participant-facing evidence files into the Northstar SQLite cache."""

from __future__ import annotations

import csv
import json
import re
import sqlite3
from pathlib import Path
from typing import Any, Dict, Iterable, Optional

SUPPORTED_EXTENSIONS = {".log", ".json", ".sql", ".csv", ".txt"}
RESOURCE_RE = re.compile(
    r"\b(?:account|search|security|audit_record|support|identity|analytics|"
    r"telemetry|data_flow|backup|export|tombstone|customer)[_-][A-Za-z0-9_-]+\b",
    re.IGNORECASE,
)
KEY_VALUE_RE = re.compile(r'''([\w.-]+)\s*[:=]\s*(?:"([^"]*)"|'([^']*)'|([^,\s}]+))''')


def _text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8-sig", errors="replace")
    except OSError:
        return ""


def _system(resource: str, fields: Dict[str, Any]) -> str:
    explicit = fields.get("system_id") or fields.get("system") or fields.get("service") or fields.get("source_system")
    if explicit:
        return str(explicit).strip()
    key = resource.casefold()
    for prefix, system in (
        ("account_", "account_service"), ("customer_", "account_service"),
        ("search_", "search_service"), ("audit_record_", "security_service"),
        ("security_", "security_service"), ("support_", "support_platform"),
        ("identity_", "identity_service"), ("analytics_", "analytics_platform"),
        ("telemetry_", "analytics_platform"), ("data_flow_", "integration_service"),
        ("backup_", "backup_service"), ("export_", "export_service"),
    ):
        if key.startswith(prefix):
            return system
    return ""


def _state(fields: Dict[str, Any]) -> str:
    values = " ".join(
        str(fields.get(key, "")) for key in
        ("verified_state", "state", "result", "status", "event", "operation")
    ).casefold()
    if re.search(r"\b(absent|not_found|not found|not_found|deleted|miss|404)\b", values):
        return "ABSENT"
    if re.search(r"\b(anonymized|anonymised)\b", values):
        return "ANONYMIZED"
    if re.search(r"\bredacted\b", values):
        return "REDACTED"
    if re.search(r"\b(present|found|hit|success|200|retained)\b", values):
        return "PRESENT"
    direct = any(fields.get(key) not in (None, "", "null", "None") for key in
                 ("email", "phone", "email_hash", "name", "user_id"))
    if fields.get("direct_identifiers") is False or str(fields.get("direct_identifiers", "")).casefold() in {"false", "0", "no"}:
        return "ANONYMIZED"
    return "PRESENT" if direct else "PRESENT"


def _records_from_json(value: Any) -> Iterable[Dict[str, Any]]:
    if isinstance(value, dict):
        if any(key in value for key in ("resource_id", "record_id", "account_id")):
            yield value
        for child in value.values():
            if isinstance(child, (dict, list)):
                yield from _records_from_json(child)
    elif isinstance(value, list):
        for child in value:
            yield from _records_from_json(child)


def _parse_line(line: str) -> Dict[str, Any]:
    line = line.strip()
    if not line:
        return {}
    start = line.find("{")
    if start >= 0:
        try:
            parsed = json.loads(line[start:])
            if isinstance(parsed, dict):
                return parsed
        except json.JSONDecodeError:
            pass
    result: Dict[str, Any] = {}
    for match in KEY_VALUE_RE.finditer(line):
        result[match.group(1)] = next((part for part in match.groups()[1:] if part is not None), "")
    if not result:
        resources = RESOURCE_RE.findall(line)
        if resources:
            result["resource_id"] = resources[0]
            result["result"] = "PRESENT"
            email = re.search(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", line)
            user = re.search(r"\buser_[A-Za-z0-9_-]+\b", line)
            if email:
                result["email"] = email.group(0)
            if user:
                result["user_id"] = user.group(0)
    return result


def index_unstructured_evidence(
    evidence_dir: Path = Path("dataset/evidence"),
    conn: Optional[sqlite3.Connection] = None,
) -> None:
    """Recursively index supported evidence formats, retaining file-level provenance."""
    evidence_path = Path(evidence_dir)
    owned_connection = conn is None
    if conn is None:
        db_path = Path("cache/northstar.db")
        db_path.parent.mkdir(parents=True, exist_ok=True)
        conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS evidence_records ("
            "file_id TEXT NOT NULL, captured_at TEXT, system_id TEXT, "
            "resource_id TEXT NOT NULL, verified_state TEXT, user_id TEXT, email TEXT, "
            "PRIMARY KEY(file_id, resource_id))"
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_evidence_records_user ON evidence_records(user_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_evidence_records_email ON evidence_records(email)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_evidence_records_resource ON evidence_records(resource_id)")

        file_meta: Dict[str, tuple[str, str]] = {}
        try:
            for file_id, file_path, captured_at in conn.execute(
                "SELECT file_id,file_path,captured_at FROM evidence_files"
            ):
                if file_path:
                    file_meta[Path(str(file_path)).name.casefold()] = (
                        str(file_id or ""), str(captured_at or "")
                    )
        except sqlite3.Error:
            pass
        manifest = evidence_path.parent / "evidence_files.csv"
        if manifest.is_file():
            with manifest.open("r", encoding="utf-8-sig", newline="") as source:
                for row in csv.DictReader(source):
                    file_path = row.get("file_path")
                    if file_path:
                        file_meta[Path(file_path).name.casefold()] = (
                            str(row.get("file_id") or ""),
                            str(row.get("captured_at") or ""),
                        )

        email_to_user: Dict[str, str] = {}
        try:
            email_to_user.update({
                str(email).strip().casefold(): str(user_id).strip()
                for user_id, email in conn.execute(
                    "SELECT user_id,email FROM user_identities WHERE user_id IS NOT NULL AND email IS NOT NULL"
                ) if email and user_id
            })
        except sqlite3.Error:
            pass

        indexed: Dict[tuple[str, str], tuple[str, str, str, str, str, Optional[str], Optional[str]]] = {}
        for path in sorted(evidence_path.rglob("*")):
            if not path.is_file() or path.suffix.casefold() not in SUPPORTED_EXTENSIONS:
                continue
            file_id, captured_at = file_meta.get(path.name.casefold(), ("", ""))
            content = _text(path)
            candidates: Iterable[Dict[str, Any]]
            if path.suffix.casefold() == ".json":
                try:
                    candidates = list(_records_from_json(json.loads(content)))
                except json.JSONDecodeError:
                    candidates = [_parse_line(line) for line in content.splitlines()]
            elif path.suffix.casefold() == ".csv":
                try:
                    candidates = list(csv.DictReader(content.splitlines()))
                except csv.Error:
                    candidates = [_parse_line(line) for line in content.splitlines()]
            else:
                candidates = [_parse_line(line) for line in content.splitlines()]

            for raw in candidates:
                fields = {str(key).casefold(): value for key, value in raw.items()}
                resource = next((fields.get(key) for key in
                                 ("resource_id", "record_id", "account_id", "id")
                                 if fields.get(key)), None)
                if not resource:
                    continue
                resource = str(resource).strip()
                if not RESOURCE_RE.fullmatch(resource):
                    continue
                system_id = _system(resource, fields)
                if not system_id:
                    continue
                email = next((fields.get(key) for key in
                              ("email", "owner_email", "customer_email", "subject_email")
                              if fields.get(key)), None)
                user_id = next((fields.get(key) for key in
                                ("user_id", "subject_ref", "subject_reference", "customer_reference")
                                if fields.get(key)), None)
                email = str(email).strip().casefold() if email else None
                user_id = str(user_id).strip() if user_id else None
                if user_id and "@" in user_id:
                    email, user_id = user_id.casefold(), None
                if email and not user_id:
                    user_id = email_to_user.get(email)
                state = _state(fields)
                key = (file_id, resource)
                indexed[key] = (
                    file_id, captured_at, system_id, resource, state, user_id, email
                )

        conn.executemany(
            "INSERT OR REPLACE INTO evidence_records "
            "(file_id,captured_at,system_id,resource_id,verified_state,user_id,email) "
            "VALUES (?,?,?,?,?,?,?)",
            indexed.values(),
        )
        conn.commit()
    finally:
        if owned_connection:
            conn.close()


if __name__ == "__main__":
    index_unstructured_evidence()

