import csv
import json
import re
import sqlite3
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Set, Tuple

SYSTEM_ORDER: Dict[str, int] = {
    "account_service": 1,
    "search_service": 2,
    "security_service": 3,
    "support_platform": 4,
    "identity_service": 5,
    "analytics_platform": 6,
    "integration_service": 7,
    "backup_service": 8,
    "export_service": 9,
}

SUPPORTED_EXTENSIONS = {".log", ".json", ".sql", ".csv", ".txt"}
RESOURCE_RE = re.compile(
    r"\b(?:account|search|security|audit_record|support|identity|analytics|"
    r"telemetry|data_flow|backup|export|tombstone|customer)[_-][A-Za-z0-9_-]+\b",
    re.IGNORECASE,
)
