    r'''([\w.-]+)\s*[:=]\s*(?:"([^"]*)"|'([^']*)'|([^,\s}]+))'''
)


def _system_for_resource(resource_id: str, fields: Dict[str, Any]) -> str:
    explicit = (
        fields.get("system_id")
        or fields.get("system")
        or fields.get("service")
        or fields.get("source_system")
    )
    if explicit:
        return str(explicit).strip()

    resource = resource_id.casefold()
    prefixes = (
        ("account_", "account_service"),
        ("customer_", "account_service"),
        ("search_", "search_service"),
        ("audit_record_", "security_service"),
        ("security_", "security_service"),
        ("support_", "support_platform"),
        ("identity_", "identity_service"),
        ("analytics_", "analytics_platform"),
        ("telemetry_", "analytics_platform"),
        ("data_flow_", "integration_service"),
        ("backup_", "backup_service"),
        ("export_", "export_service"),
    )
    return next(
        (system for prefix, system in prefixes if resource.startswith(prefix)),
        "",
    )


def _system_for_table(table_name: str) -> str:
    table = table_name.casefold()
    for token, system in (
        ("analytics", "analytics_platform"),
        ("telemetry", "analytics_platform"),
        ("search", "search_service"),
        ("support", "support_platform"),
        ("audit", "security_service"),
        ("security", "security_service"),
        ("backup", "backup_service"),
        ("flow", "integration_service"),
        ("export", "export_service"),
        ("account", "account_service"),
        ("customer", "account_service"),
        ("profile", "account_service"),
    ):
        if token in table:
            return system
    return ""


def _evidence_row_state(fields: Dict[str, Any]) -> str:
    text = " ".join(
        str(fields.get(key, ""))
        for key in ("verified_state", "state", "result", "status", "event", "operation")
    ).casefold()
    if re.search(r"\b(absent|not_found|not found|deleted|miss|404)\b", text):
        return "ABSENT"
    if re.search(r"\b(anonymized|anonymised)\b", text):
        return "ANONYMIZED"
    if re.search(r"\bredacted\b", text):
        return "REDACTED"
    return "PRESENT"


def _records_from_json(value: Any) -> Iterable[Dict[str, Any]]:
    if isinstance(value, dict):
        if any(key in value for key in ("resource_id", "record_id", "account_id")):
            yield value
        for child in value.values():
            if isinstance(child, (dict, list)):
                yield from _records_from_json(child)
    elif isinstance(value, list):
        for child in value:
            yield from _records_from_json(child)


def _parse_evidence_line(line: str) -> Dict[str, Any]:
    stripped = line.strip()
    if not stripped:
        return {}
    brace = stripped.find("{")
    if brace >= 0:
        try:
            parsed = json.loads(stripped[brace:])
            if isinstance(parsed, dict):
                return parsed
        except json.JSONDecodeError:
            pass

    fields: Dict[str, Any] = {}
    for match in KEY_VALUE_RE.finditer(stripped):
        fields[match.group(1)] = next(
            (value for value in match.groups()[1:] if value is not None),
            "",
        )
    if fields:
        return fields

    resource_match = RESOURCE_RE.search(stripped)
    if resource_match:
        fields["resource_id"] = resource_match.group(0)
        fields["result"] = "PRESENT"
        email = re.search(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", stripped)
        user_id = re.search(r"\buser_[A-Za-z0-9_-]+\b", stripped)
        if email:
            fields["email"] = email.group(0)
        if user_id:
            fields["user_id"] = user_id.group(0)
    return fields


def _read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8-sig", errors="replace")
    except OSError:
