        email = re.search(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", stripped)
        user_id = re.search(r"\buser_[A-Za-z0-9_-]+\b", stripped)
        if email:
            fields["email"] = email.group(0)
        if user_id:
            fields["user_id"] = user_id.group(0)
    return fields


def _read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8-sig", errors="replace")
    except OSError:
        return ""


def index_unstructured_evidence(
    evidence_dir: Path = Path("dataset/evidence"),
    conn: Optional[sqlite3.Connection] = None,
) -> None:
    """Recursively index supported evidence files with per-file provenance."""
    evidence_path = Path(evidence_dir)
    owns_connection = conn is None
    if conn is None:
        db_path = Path("cache/northstar.db")
        db_path.parent.mkdir(parents=True, exist_ok=True)
        conn = sqlite3.connect(db_path)

    try:
        exists = conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='evidence_records'"
        ).fetchone()
        if exists:
            primary_key = [
                row[1]
                for row in sorted(
                    (
                        row
                        for row in conn.execute(
                            'PRAGMA table_info("evidence_records")'
                        )
                        if row[5]
                    ),
                    key=lambda row: row[5],
                )
            ]
            if primary_key != ["file_id", "resource_id"]:
                conn.execute("DROP TABLE evidence_records")

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS evidence_records (
                file_id TEXT NOT NULL,
                captured_at TEXT,
                system_id TEXT,
                resource_id TEXT NOT NULL,
                verified_state TEXT,
                user_id TEXT,
                email TEXT,
                PRIMARY KEY(file_id, resource_id)
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_evidence_records_user "
            "ON evidence_records(user_id)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_evidence_records_email "
            "ON evidence_records(email)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_evidence_records_resource "
            "ON evidence_records(resource_id)"
        )

        file_metadata: Dict[str, Tuple[str, str]] = {}
        try:
            for file_id, file_path, captured_at in conn.execute(
                "SELECT file_id,file_path,captured_at FROM evidence_files"
            ):
                if file_path:
                    file_metadata[Path(str(file_path)).name.casefold()] = (
                        str(file_id or ""),
                        str(captured_at or ""),
                    )
        except sqlite3.Error:
            pass

        manifest_path = evidence_path.parent / "evidence_files.csv"
        if manifest_path.is_file():
            with manifest_path.open(
                "r", encoding="utf-8-sig", newline=""
            ) as source:
                for row in csv.DictReader(source):
                    file_path = row.get("file_path")
                    if file_path:
                        file_metadata[Path(file_path).name.casefold()] = (
                            str(row.get("file_id") or ""),
                            str(row.get("captured_at") or ""),
                        )

        email_to_user: Dict[str, str] = {}
        try:
            email_to_user.update(
                {
                    str(email).strip().casefold(): str(user_id).strip()
                    for user_id, email in conn.execute(
                        "SELECT user_id,email FROM user_identities "
                        "WHERE user_id IS NOT NULL AND email IS NOT NULL"
                    )
                    if user_id and email
                }
            )
        except sqlite3.Error:
            pass

        indexed: Dict[
            Tuple[str, str],
            Tuple[str, str, str, str, str, Optional[str], Optional[str]],
        ] = {}

        for path in sorted(evidence_path.rglob("*")):
            if not path.is_file() or path.suffix.casefold() not in SUPPORTED_EXTENSIONS:
                continue
            file_id, captured_at = file_metadata.get(
                path.name.casefold(), ("", "")
            )
            content = _read_text(path)

            if path.suffix.casefold() == ".json":
                try:
                    candidates = list(_records_from_json(json.loads(content)))
                except json.JSONDecodeError:
                    candidates = [
                        _parse_evidence_line(line)
                        for line in content.splitlines()
                    ]
            elif path.suffix.casefold() == ".csv":
                try:
                    candidates = list(csv.DictReader(content.splitlines()))
                except csv.Error:
                    candidates = [
                        _parse_evidence_line(line)
                        for line in content.splitlines()
                    ]
            elif path.suffix.casefold() == ".sql":
                candidates = []
                snapshot = sqlite3.connect(":memory:")
                try:
                    snapshot.executescript(content)
                    table_names = [
                        row[0]
                        for row in snapshot.execute(
                            "SELECT name FROM sqlite_master "
                            "WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                        )
                    ]
                    for table_name in table_names:
                        columns = [
                            row[1]
                            for row in snapshot.execute(
                                'PRAGMA table_info("{}")'.format(
                                    table_name.replace('"', '""')
                                )
                            )
                        ]
                        quoted_table = table_name.replace('"', '""')
                        for values in snapshot.execute(
                            f'SELECT * FROM "{quoted_table}"'
                        ):
                            record = {
                                str(column).casefold(): value
                                for column, value in zip(columns, values)
                            }
                            resource_key = next(
                                (
                                    key
                                    for key in (
                                        "resource_id",
                                        "record_id",
                                        "account_id",
                                        "id",
                                    )
                                    if record.get(key)
                                ),
                                None,
                            )
                            if resource_key:
                                resource = str(record[resource_key]).strip()
                                if RESOURCE_RE.fullmatch(resource):
                                    record.setdefault(
                                        "system_id",
                                        _system_for_table(table_name),
                                    )
                                    candidates.append(record)
                except sqlite3.Error:
                    candidates = [
                        _parse_evidence_line(line)
                        for line in content.splitlines()
                    ]
                finally:
                    snapshot.close()
            else:
                candidates = [
                    _parse_evidence_line(line)
                    for line in content.splitlines()
                ]

            for raw_record in candidates:
                fields = {
                    str(key).casefold(): value
                    for key, value in raw_record.items()
                }
                resource_value = next(
                    (
                        fields.get(key)
                        for key in ("resource_id", "record_id", "account_id", "id")
                        if fields.get(key)
                    ),
                    None,
                )
                if not resource_value:
                    continue
                resource_id = str(resource_value).strip()
                if not RESOURCE_RE.fullmatch(resource_id):
                    continue
                system_id = (
                    _system_for_resource(resource_id, fields)
                    or _system_for_table(path.stem)
                )
                if not system_id:
                    continue

                email_value = next(
                    (
                        fields.get(key)
                        for key in (
                            "email",
                            "owner_email",
                            "customer_email",
                            "subject_email",
                        )
                        if fields.get(key)
                    ),
                    None,
                )
                user_value = next(
                    (
                        fields.get(key)
                        for key in (
                            "user_id",
                            "subject_ref",
                            "subject_reference",
                            "customer_reference",
                        )
                        if fields.get(key)
                    ),
                    None,
                )
                email = str(email_value).strip().casefold() if email_value else None
                user_id = str(user_value).strip() if user_value else None
                if user_id and "@" in user_id:
                    email, user_id = user_id.casefold(), None
                if email and not user_id:
                    user_id = email_to_user.get(email)

                indexed[(file_id, resource_id)] = (
                    file_id,
                    captured_at,
                    system_id,
                    resource_id,
                    _evidence_row_state(fields),
                    user_id,
                    email,
                )

        conn.executemany(
            """
            INSERT OR REPLACE INTO evidence_records
            (file_id,captured_at,system_id,resource_id,verified_state,user_id,email)
            VALUES (?,?,?,?,?,?,?)
            """,
            indexed.values(),
        )
        conn.commit()
    finally:
        if owns_connection:
            conn.close()

