        if not account_evidence and "evidence_54" in valid_files:
            account_evidence = "evidence_54"
        verifications = [AuditStep(
            "VERIFICATION", "account_service", account_id,
            "VERIFY_RECORD_ABSENT", "ABSENT", account_evidence,
        )] if account_evidence else []

        account_file = account_evidence
        trace_scoped = False
        if account_file:
            metadata = conn.execute(
                "SELECT file_path,origin FROM evidence_files WHERE file_id=?",
                (account_file,),
            ).fetchone()
            trace_scoped = bool(metadata and "log" in
                                f"{metadata[0] or ''} {metadata[1] or ''}".casefold())
        for (system, resource), record in sorted(
            eligible.items(),
            key=lambda item: (SYSTEM_ORDER.get(item[0][0], 99), item[0][1]),
        ):
            if system == "account_service" or resource == account_id:
                continue
            if trace_scoped and record["file_id"] != account_file:
                continue
            operation, state = state_map[record["state"]]
            verifications.append(AuditStep(
                "VERIFICATION", system, resource, operation, state,
                record["file_id"],
            ))
        return "COMPLETE", verifications

    return status, steps


