                raise ValueError(
                    f"COMPLETE verification step on {step.system_id}/{step.resource_id} "
                    "must cite a file_id, activity_id, or audit_id."
                )
            evidence_id = step.evidence_id
        elif step.phase == "FINDING":
            if not step.evidence_id:
                raise ValueError(
                    f"INCOMPLETE finding step on {step.system_id}/{step.resource_id} "
                    "must cite a file_id, activity_id, or audit_id."
                )
            evidence_id = step.evidence_id
        else:
            evidence_id = ""

        normalized[
            (step.phase, step.operation, step.system_id, step.resource_id)
        ] = AuditStep(
            phase=step.phase,
            system_id=step.system_id,
            resource_id=step.resource_id,
            operation=step.operation,
            state=state,
            evidence_id=evidence_id,
        )

    ordered = _canonicalize_audit_steps(list(normalized.values()))
    payload = [
        {
            "step_no": index,
            "phase": step.phase,
            "system_id": step.system_id,
            "resource_id": step.resource_id,
            "operation": step.operation,
            "state": step.state,
            "evidence_id": step.evidence_id,
        }
        for index, step in enumerate(ordered, start=1)
    ]
    return json.dumps(payload, separators=(",", ":"))


def expand_findings_to_plan(
    findings: List[Tuple[AuditStep, Optional[str]]],
    retained_verifications: Optional[List[AuditStep]] = None,
) -> List[AuditStep]:
    plan: List[AuditStep] = []
    for finding, treatment in findings:
        plan.append(finding)
        treatment_key = (
            None
            if finding.operation in {
                "REPORT_ACTIVE_DATA_FLOW",
                "REPORT_RESTORE_RISK",
                "REPORT_EXPOSED_PII",
            }
            else treatment
        )
        mapping = REMEDIATION_MAP.get((finding.operation, treatment_key))
        if mapping is None:
            raise ValueError(
                f"No remediation mapping for {(finding.operation, treatment)}"
            )
        remediation_operation, verification_operation = mapping
        remediation_state = ALLOWED_OPERATIONS[
            ("REMEDIATION", remediation_operation)
        ][1]
        verification_state = ALLOWED_OPERATIONS[
            ("VERIFICATION", verification_operation)
        ][1]
        plan.extend(
            (
                AuditStep(
                    "REMEDIATION",
                    finding.system_id,
                    finding.resource_id,
                    remediation_operation,
                    remediation_state,
                    "",
                ),
                AuditStep(
                    "VERIFICATION",
                    finding.system_id,
                    finding.resource_id,
                    verification_operation,
                    verification_state,
                    "",
                ),
            )
        )

    for verification in retained_verifications or []:
        plan.append(
            AuditStep(
                "VERIFICATION",
                verification.system_id,
                verification.resource_id,
                verification.operation,
                verification.validated_state(),
                "",
            )
        )
    return _canonicalize_audit_steps(plan)
